insert into public.title_proposals (seed_key, batch, origin_ref, original_title, title, summary, hardware, communication, status, assigned_to, assigned_at) values
  ('new-ete-A1', 'New solution titles (BENG22 ETE)', 'ETE Panel A No. 1', 'Analysis of the Quality for Local Alcoholic Beverages', 'Handheld Alcohol Strength and Methanol Risk Screening Device for Local Brew Sellers', 'A pocket device that measures alcohol strength (% by volume) from density and temperature, and uses a gas sensor array to flag a sample whose vapour pattern does not match a normal ethanol brew. The screen shows Normal, Strong, or Send to lab.', 'Density sensor or load-cell hydrometer, temperature probe, gas sensor array with a trained classifier, ESP32, small display, sample log.', null, 'available', null, null),
  ('new-ete-B9', 'New solution titles (BENG22 ETE)', 'ETE Panel B No. 9', 'Milk Quality Detection System Using Machine Learning for Industrial Use', 'Milk Collection Centre Quality Screening and Quality-Based Farmer Payment System', 'A bench unit at the collection centre tests each farmer''s can for density, conductivity, pH, and temperature. It records the result against the farmer''s card or phone number, grades the milk, and sends an SMS receipt with litres, grade, and price.', 'Lactometer or density sensor, conductivity probe, pH probe, temperature probe, load cell, RFID reader, ESP32 with GSM, web dashboard.', 'GSM SMS receipts to farmers; upload to a web dashboard.', 'available', null, null),
  ('new-ete-A15', 'New solution titles (BENG22 ETE)', 'ETE Panel A No. 15', 'Smart Crops Protection System from Birds', 'Solar Camera-Triggered Bird Deterrent for Rice and Sorghum Fields', 'A solar pole with a camera and a small on-device model detects a flock landing. Only then it fires a changing deterrent: a random sound pattern, a moving reflector, or a flashing light. It texts the farmer during heavy attacks.', 'ESP32-CAM or Raspberry Pi with camera, solar panel and battery, speaker, servo reflector, flashing light, GSM module.', 'GSM SMS to the farmer during heavy attacks.', 'available', null, null),
  ('new-ete-B26', 'New solution titles (BENG22 ETE)', 'ETE Panel B No. 26', 'Real-Time Monitoring System for Adulterated Fuel in Motorcycle Refuelling', 'In-Tank Fuel Quality Sensor and Rider Warning for Boda-Boda Motorcycles', 'A small sensor on the motorcycle measures the fuel''s dielectric value and temperature after each refill. If the fuel reads like petrol mixed with kerosene, it warns the rider and saves the time and station location as evidence.', 'Capacitive fuel sensor cell, temperature sensor, ESP32 with Bluetooth, LED and buzzer, sealed petrol-rated housing.', 'Bluetooth to a phone app with GPS.', 'available', null, null),
  ('new-ete-A22', 'New solution titles (BENG22 ETE)', 'ETE Panel A No. 22', 'IoT-Enabled Smart Notice Board', 'Accessible Campus Notice and Emergency Alert Board with Audio and Sign-Language Output', 'Networked display boards updated from one web page. Each notice can be read aloud in Swahili or English, shown with a short sign-language clip, and sent by SMS. Emergency mode takes over every board with a flashing alert and a siren.', 'Raspberry Pi with screen or LED matrix, speaker, large button with Braille label, flashing beacon, GSM module.', 'Network link to a web admin page; GSM SMS broadcast.', 'available', null, null),
  ('coe-hw-1', 'ETE hardware topics (from BENG22 COE)', 'COE No. 9', 'Development of QR Code & Coin Based Mobile Phone Charging System', 'Solar Coin and Mobile-Money Phone Charging Kiosk with Per-Port Power Metering', 'A solar kiosk with several charging ports. Users pay by coin or mobile money, and each port is metered and switched off when the paid energy or time runs out.', 'Solar panel, MPPT charger, 12 V LiFePO4 battery, per-port current sensing and switching, coin acceptor, embedded controller, display.', 'GSM module for mobile-money confirmation and status reports.', 'available', null, null),
  ('coe-hw-2', 'ETE hardware topics (from BENG22 COE)', 'COE No. 10', 'Tanzanian Sign Language Gestures to Voice Translator for Medical Communication', 'Wearable Sensor Glove that Converts Tanzanian Sign Language to Speech in Clinics', 'A glove with finger-bend and motion sensors recognises Tanzanian Sign Language gestures and speaks the words aloud so deaf patients can talk to clinic staff.', 'Flex sensors, IMU, embedded controller with gesture classifier, speaker and audio amplifier, rechargeable battery.', 'Bluetooth to a phone app for text display and new gesture training.', 'available', null, null),
  ('coe-hw-3', 'ETE hardware topics (from BENG22 COE)', 'COE Nos. 99, 65, 77', 'IoT Helmet for Miners / AI Based Industrial Safety Monitoring System for Mining Industry', 'Smart Mining Helmet with Gas Detection, Fall Alarm, and LoRa Link to the Surface', 'A helmet unit that detects dangerous gases, falls, and missing movement, sounds a local alarm, and sends the alert to the surface control room.', 'Gas sensors (CH4, CO), accelerometer for fall detection, panic button, buzzer and LED, controller, rechargeable battery.', 'LoRa link through underground relay nodes to a surface gateway.', 'available', null, null),
  ('coe-hw-4', 'ETE hardware topics (from BENG22 COE)', 'COE Nos. 62, 91', 'IoT-Enabled Remote Monitoring and Smart Triage System for Chronic Cardiac Patients', 'Wearable ECG and SpO2 Patch with Phone Relay for Remote Cardiac Patient Triage', 'A chest patch records ECG and oxygen level at home and relays readings through the patient''s phone so clinicians can see who needs attention first.', 'ECG analog front end, SpO2 sensor, low-power controller, rechargeable battery, wearable enclosure.', 'Bluetooth Low Energy to a phone that uploads to a clinic dashboard.', 'available', null, null),
  ('coe-hw-5', 'ETE hardware topics (from BENG22 COE)', 'COE No. 95', 'IoT Based Maternal Risk Prediction and Assistance System', 'Low-Cost Antenatal Check Kit with Fetal Doppler and Blood Pressure for Rural Dispensaries', 'A portable kit that measures fetal heart rate and the mother''s blood pressure at rural dispensaries and flags high-risk pregnancies for referral.', 'Ultrasound Doppler probe and front end, automatic BP cuff with pressure sensor, controller, display, battery.', 'GSM SMS referral alerts and record upload.', 'available', null, null),
  ('coe-hw-6', 'ETE hardware topics (from BENG22 COE)', 'COE No. 101', 'Automated Zebra Crossing Safety System', 'Radar-Activated Smart Zebra Crossing with Solar LED Road Studs and Speeding Warning', 'Radar detects pedestrians waiting and approaching vehicles; solar LED road studs flash and a speed sign warns drivers who are going too fast.', 'Pedestrian and vehicle radar modules, solar LED road studs, speed display sign, controller, solar power unit.', 'Wireless link between the pole controller and the road studs.', 'available', null, null),
  ('coe-hw-7', 'ETE hardware topics (from BENG22 COE)', 'COE No. 89', 'Developing a Smart Air Condition Electricity Consumption Monitoring and Control System', 'Plug-In Air Conditioner Energy Meter and IR Controller for Offices and Lecture Rooms', 'A plug-in unit meters each air conditioner''s energy use and switches it off or adjusts it by infrared when rooms are empty or out of hours.', 'Energy metering IC, current transformer, relay, IR transmitter, occupancy sensor, controller.', 'Wi-Fi to an energy dashboard.', 'available', null, null),
  ('coe-hw-8', 'ETE hardware topics (from BENG22 COE)', 'COE No. 40', 'Development of Satellite Image Based Flood Risk Prediction System', 'Solar River-Level and Rainfall Station Network for Community Flood Early Warning', 'Solar stations measure river level and rainfall along a river and send early flood warnings to communities downstream.', 'Ultrasonic or radar level sensor, tipping-bucket rain gauge, controller, solar panel and battery, siren.', 'LoRa between stations and a gateway; GSM SMS alerts to residents.', 'available', null, null),
  ('coe-hw-9', 'ETE hardware topics (from BENG22 COE)', 'COE No. 64', 'Development of Rice Quality Assessment System', 'Benchtop Rice Grain Quality Analyser with Imaging Chamber and Moisture Measurement', 'A benchtop unit photographs a rice sample in a controlled light chamber to count broken and discoloured grains and measures moisture to grade the rice.', 'Camera with controlled LED lighting chamber, capacitive moisture sensor, load cell, embedded processor, display.', 'Wi-Fi upload of grading results.', 'available', null, null),
  ('coe-hw-10', 'ETE hardware topics (from BENG22 COE)', 'COE Nos. 105, 56', 'Development of a Smart Exhibition Navigation System (Indoor and Outdoor)', 'UWB Indoor Positioning Network for Exhibition Halls and Hospitals', 'Ultra-wideband anchors locate visitors'' tags to within centimetres so a phone app can guide them to stands or hospital departments.', 'UWB anchor nodes, UWB tags, controller, power supplies for anchors.', 'UWB ranging; Bluetooth from tag to phone app.', 'available', null, null),
  ('jecsa-1', 'To Jecsa', 'COE No. 57', 'Intelligent Geolocation Based Ambulance Booking System', 'Ambulance Patient Telemetry Unit that Streams Live Vital Signs and GPS Location to the Receiving Hospital', 'A unit fixed in the ambulance measures the patient''s ECG, heart rate, oxygen level, blood pressure, and temperature on the way, and sends the readings and the ambulance location to the emergency department every few seconds.', 'ECG analog front end, SpO2 sensor, automatic BP cuff with pump and pressure sensor, temperature probe, GNSS receiver, 12 V vehicle power input with protection and backup battery, embedded controller, and display for the paramedic.', '4G LTE modem with SMS fallback when data coverage is weak.', 'reserved', 'Jecsa', now ()),
  ('jecsa-2', 'To Jecsa', 'New idea', null, 'Digital Forest Canopy Densiometer with Fisheye Camera, Tilt Correction and GPS Tagging for Forest Cover Monitoring', 'A handheld device replaces the mirror densiometer with an upward-facing fisheye camera. It checks that it is level, takes the sky picture, separates sky from leaves, and gives the canopy cover percentage in seconds, tagged with GPS location and time.', 'Camera module with fisheye lens, IMU for level checking and tilt correction, GNSS receiver, PAR light sensor, embedded processor, display and buttons, microSD storage, rechargeable battery in a rugged enclosure.', 'LoRa to a base station at the forest edge; GSM/4G upload when signal is available; Bluetooth to a phone app.', 'reserved', 'Jecsa', now ()),
  ('jecsa-3', 'To Jecsa', 'COE No. 104', 'Beacon Tracking System for Land Plot Validation', 'Development of RTK GNSS Smart Boundary Beacons with LoRa Tamper Alerts: A Case Study of Game Reserve Land Protection', 'Each game reserve boundary beacon has a GNSS receiver and tamper sensors sealed inside the post. If it is tilted, dug out, lifted, or moved, it alerts the ranger post, and a hand-held RTK rover lets rangers restore the exact corner.', 'Beacon unit with GNSS module, accelerometer, tamper switch and light sensor, low-power controller, LoRa radio, solar-charged battery; RTK base station; hand-held RTK rover.', 'LoRaWAN from beacons to a ranger-post gateway; GSM/4G to the boundary map server; SMS alerts to rangers.', 'reserved', 'Jecsa', now ())
