-- Title bank: last year's student projects (from the Excel lists in docs/) and new titles for selection.
-- Run in Supabase SQL editor. Safe to re-run: seed rows use seed_key and skip rows that already exist.

create table if not exists public.last_year_projects (
  id uuid primary key default gen_random_uuid (),
  seed_key text unique,
  programme text not null check (programme in ('ETE', 'COE')),
  source text not null,
  panel text null,
  serial_no integer null,
  reg_no text null,
  student_name text null,
  title text not null,
  supervisor text null,
  notes text null,
  created_at timestamptz not null default now (),
  updated_at timestamptz not null default now ()
);

create index if not exists last_year_projects_programme_idx
  on public.last_year_projects (programme, panel, serial_no);

create table if not exists public.title_proposals (
  id uuid primary key default gen_random_uuid (),
  seed_key text unique,
  batch text null,
  origin_ref text null,
  original_title text null,
  title text not null,
  summary text null,
  hardware text null,
  communication text null,
  status text not null default 'available'
    check (status in ('available', 'reserved', 'assigned', 'dropped')),
  assigned_to text null,
  assigned_at timestamptz null,
  notes text null,
  created_at timestamptz not null default now (),
  updated_at timestamptz not null default now ()
);

create index if not exists title_proposals_status_idx
  on public.title_proposals (status, created_at);

comment on column public.title_proposals.status is
  'available: open for selection. reserved: held for someone. assigned: given to a student/team. dropped: no longer offered.';

-- Student names and registration numbers: no anon access. The dashboard uses the service role.
alter table public.last_year_projects enable row level security;
alter table public.title_proposals enable row level security;

drop policy if exists "last_year_projects_auth_all" on public.last_year_projects;
create policy "last_year_projects_auth_all"
on public.last_year_projects for all to authenticated using (true) with check (true);

drop policy if exists "title_proposals_auth_all" on public.title_proposals;
create policy "title_proposals_auth_all"
on public.title_proposals for all to authenticated using (true) with check (true);

-- Seed: last year projects (150 rows; rows with no title on the sheet are skipped)
on conflict (seed_key) do nothing;

-- Seed: new titles for selection (18 rows)
on conflict (seed_key) do nothing;
